#include <stdio.h>

int biggest(int fish[], int count) {
    if (count <= 0) {
        return -1;
    }
    int best = fish[0];
    for (int i = 1; i < count; i++) {
        if (fish[i] > best) {
            best = fish[i];
        }
    }
    return best;
}

int main(void) {
    int fish[3] = { {a}, {b}, {c} };
    printf("三碗：%d\n", biggest(fish, 3));
    printf("一碗都没有：%d\n", biggest(fish, 0));
    return 0;
}
